package com.nextfeet.nextfeet.controller; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import com.nextfeet.nextfeet.model.*; import com.nextfeet.nextfeet.service.*; @Controller @RequestMapping("/admin") public class AdminController {private final UsuarioService users;private final CategoriaService cats;private final ZapatillaService shoes;private final PedidoService orders;private final OfertaService offers; public AdminController(UsuarioService u,CategoriaService c,ZapatillaService z,PedidoService o,OfertaService f){users=u;cats=c;shoes=z;orders=o;offers=f;} @GetMapping("/dashboard") public String dash(){return "admin/dashboard";} @GetMapping("/administradores") public String admins(Model m){m.addAttribute("usuarios",users.listar("ADMIN"));return "admin/administradores";} @PostMapping("/administradores/crear") public String crearAdmin(@ModelAttribute Usuario u){u.setRol("ADMIN");users.registrar(u);return "redirect:/admin/administradores";} @PostMapping("/administradores/desactivar") public String desAdmin(@RequestParam Integer id){users.desactivar(id);return "redirect:/admin/administradores";} @GetMapping("/clientes") public String clientes(Model m){m.addAttribute("usuarios",users.listar("CLIENTE"));return "admin/clientes";} @PostMapping("/clientes/actualizar") public String editCliente(@ModelAttribute Usuario u){users.actualizar(u);return "redirect:/admin/clientes";} @PostMapping("/clientes/desactivar") public String desCliente(@RequestParam Integer id){users.desactivar(id);return "redirect:/admin/clientes";} @GetMapping("/categorias") public String categorias(Model m){m.addAttribute("categorias",cats.listar());m.addAttribute("categoria",new Categoria());return "admin/categorias";} @PostMapping("/categorias/crear") public String crearCat(@ModelAttribute Categoria c){cats.crear(c);return "redirect:/admin/categorias";} @PostMapping("/categorias/actualizar") public String actCat(@ModelAttribute Categoria c){cats.actualizar(c);return "redirect:/admin/categorias";} @PostMapping("/categorias/desactivar") public String desCat(@RequestParam Integer id){cats.desactivar(id);return "redirect:/admin/categorias";} @GetMapping("/zapatillas") public String shoes(Model m){m.addAttribute("zapatillas",shoes.listar());m.addAttribute("zapatilla",new Zapatilla());return "admin/zapatillas";} @PostMapping("/zapatillas/crear") public String crearShoe(@ModelAttribute Zapatilla z){shoes.crear(z);return "redirect:/admin/zapatillas";} @PostMapping("/zapatillas/actualizar") public String actShoe(@ModelAttribute Zapatilla z){shoes.actualizar(z);return "redirect:/admin/zapatillas";} @PostMapping("/zapatillas/desactivar") public String desShoe(@RequestParam Integer id){shoes.desactivar(id);return "redirect:/admin/zapatillas";} @PostMapping("/zapatillas/eliminar") public String delShoe(@RequestParam Integer id){shoes.eliminar(id);return "redirect:/admin/zapatillas";} @GetMapping("/pedidos") public String pedidos(Model m){m.addAttribute("pedidos",orders.listarTodos());return "admin/pedidos";} @PostMapping("/pedidos/estado") public String estado(@RequestParam Integer id,@RequestParam String estado){orders.actualizarEstado(id,estado);return "redirect:/admin/pedidos";} @PostMapping("/pedidos/anular") public String anular(@RequestParam Integer id,@RequestParam String motivo){orders.anular(id,motivo);return "redirect:/admin/pedidos";} @GetMapping("/ofertas") public String ofertas(Model m){m.addAttribute("ofertas",offers.listar());m.addAttribute("oferta",new Oferta());return "admin/ofertas";} @PostMapping("/ofertas/crear") public String crearOferta(@ModelAttribute Oferta o){offers.crear(o);return "redirect:/admin/ofertas";} @PostMapping("/ofertas/actualizar") public String actOferta(@ModelAttribute Oferta o){offers.actualizar(o);return "redirect:/admin/ofertas";} @PostMapping("/ofertas/desactivar") public String desOferta(@RequestParam Integer id){offers.desactivar(id);return "redirect:/admin/ofertas";} }